\usepackage{subcaption}

\graphicspath{{figures/}}

\title{Strong Predictors, Weak Selectors:\\ Why Confidence Signals Fail to Scale Structured Information Extraction}

\author{Anonymous}

\begin{document}
\maketitle

\input{sections/abstract}
